            "stdout": gcc_cp.stdout,
            "stderr": gcc_cp.stderr,
            "translate_ms": translate_ms,
            "gcc_ms": gcc_ms,
        }

    return {
        "ok": True,
        "generated_c": generated_c,
        "binary": binary,
        "translate_ms": translate_ms,
        "gcc_ms": gcc_ms,
